      worstCarrier ? insight('提货达成关注', `${worstCarrier.name} · ${pct(rate(worstCarrier.actual, worstCarrier.plan))}`, `在有应提计划的承运商中达成率最低，尚未提货 ${fmt(worstCarrier.plan - worstCarrier.actual)} 件。达成率是当前状态快照。`, 'blue') : insight('提货达成', a.carriers.some(group => group.plan > 0) ? '当日计划已全部提货' : '暂无当日应提计划', '沿用生产日期次日口径，并将生产日 00:00–12:00 纳入当天。', 'blue'),
      bottleneck ? insight('阶段用时对比', `${bottleneck.name} · P50 ${fmt(bottleneck.p50, 1)} h`, `有效样本 ${bottleneck.count} 单，P90 ${fmt(bottleneck.p90, 1)} 小时；这是中位用时最长的阶段，可优先复核样本。`, 'amber') : insight('链路样本', '暂无可比较阶段', '有效时间差需要起止时间齐全且终点不早于起点。', 'amber')
