    const cards = [kpi('当日计划提货', fmt(m.plan), '件', `${fmt(a.planSpCount)} 个SP合单 · SOO件数求和 · 前一日全日 + 当日 00:00–12:00`), kpi('对应生产计划装载率', pct(rate(m.done, m.plan)), '', `已装载 ${fmt(m.done)} / 计划 ${fmt(m.plan)} 件`, 'blue', rate(m.done, m.plan)), kpi('当日提货达成', pct(rate(m.actual, m.priorPlan)), '', `状态已提 ${fmt(m.actual)} / 应提 ${fmt(m.priorPlan)} 件`, 'teal', rate(m.actual, m.priorPlan)), kpi('当前待提规模', fmt(m.waiting), '件', `${fmt(spGroups(m.waitingRows).size)} 个SP合单 · SOO件数求和 · 截至业务日期截止日`), kpi('超时待提占比', pct(rate(m.overdue, m.waiting)), '', `超时 ${fmt(m.overdue)} 件 / 待提 ${fmt(m.waiting)} 件`, m.overdueRows.length ? 'red' : 'teal', rate(m.overdue, m.waiting)), kpi('全程中位用时', fmt(a.stages[3].p50, 1), '小时', `建单至离园 · 有效样本 ${a.stages[3].count} 个SP`, 'blue')].join('');
