    const legend = entries => `<div class="legend">${entries.map(([name, color]) => `<span><i style="background:${color}"></i>${esc(name)}</span>`).join('')}</div>`;
    const sectionTitle = (number, title, sub) => `<div class="section-title"><span>${number}</span><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div></div>`;
    const dailyRows = a.daily.map(row => [dateLabel(row.day), fmt(row.plan), fmt(row.done), pct(rate(row.done, row.plan)), fmt(row.actual), pct(rate(row.actual, row.plan))]);
    const warehouseRows = a.warehouses.map(row => [row.name, fmt(row.plan), fmt(row.done), pct(rate(row.done, row.plan)), fmt(row.waiting), fmt(row.overdue), pct(rate(row.overdue, row.waiting))]);
